-- Wächter Migration 211 (nur lesen). Erwartungen: werkzeuge/m211_md5.json. funktionen = die von 211 geänderten und neuen Funktionen.
SELECT (SELECT md5(string_agg(p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')|' || pg_get_function_result(p.oid) || '|' || md5(p.prosrc), E'\n' ORDER BY p.proname::text || '(' || pg_get_function_identity_arguments(p.oid) || ')' COLLATE "C")) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname::text = 'public' COLLATE "C" AND p.proname::text COLLATE "C" = ANY (ARRAY['ally_update_ui', 'ally_update_ui_aktion', 'ally_update_host_plan', 'ally_update_zeit', 'ally_update_phasen', 'ally_update_suche_ende'])) AS funktionen;
